52	export class Agent {
53	  #client: KeycloakAdminClient;
54	  #basePath: string;
55	  #getBaseParams?: () => Record<string, any>;
56	  #getBaseUrl: () => string;
57	
58	  constructor({
59	    client,
60	    path = "/",
61	    getUrlParams = () => ({}),
62	    getBaseUrl = () => client.baseUrl,
63	  }: {
64	    client: KeycloakAdminClient;
65	    path?: string;
66	    getUrlParams?: () => Record<string, any>;
67	    getBaseUrl?: () => string;
68	  }) {
69	    this.#client = client;
70	    this.#getBaseParams = getUrlParams;
71	    this.#getBaseUrl = getBaseUrl;
72	    this.#basePath = path;
73	  }
74	
75	  public request({
76	    method,
77	    path = "",
78	    urlParamKeys = [],
79	    queryParamKeys = [],
80	    catchNotFound = false,
81	    keyTransform,
82	    payloadKey,
83	    returnResourceIdInLocationHeader,
84	    ignoredKeys,
85	    headers,
86	  }: RequestArgs) {
87	    return async (
88	      payload: any = {},
89	      options?: Pick<RequestArgs, "catchNotFound">,
90	    ) => {
91	      const baseParams = this.#getBaseParams?.() ?? {};
92	
93	      // Filter query parameters by queryParamKeys
94	      const queryParams =
95	        queryParamKeys.length > 0
96	          ? (pick(payload, queryParamKeys) as any)
97	          : undefined;
98	
99	      // Add filtered payload parameters to base parameters
100	      const allUrlParamKeys = [...Object.keys(baseParams), ...urlParamKeys];
101	      const urlParams = { ...baseParams, ...pick(payload, allUrlParamKeys) };
102	
103	      if (!(payload instanceof FormData)) {
104	        // Omit url parameters and query parameters from payload
105	        const omittedKeys = ignoredKeys
106	          ? [...allUrlParamKeys, ...queryParamKeys].filter(
107	              (key) => !ignoredKeys.includes(key),
108	            )
109	          : [...allUrlParamKeys, ...queryParamKeys];
110	
111	        payload = omit(payload, omittedKeys);
112	      }
113	
114	      // Transform keys of both payload and queryParams
115	      if (keyTransform) {
116	        this.#transformKey(payload, keyTransform);
117	        this.#transformKey(queryParams, keyTransform);
118	      }
119	
120	      return this.#requestWithParams({
121	        method,
122	        path,
123	        payload,
124	        urlParams,
125	        queryParams,
126	        // catchNotFound precedence: global > local > default
127	        catchNotFound,
128	        ...(this.#client.getGlobalRequestArgOptions() ?? options ?? {}),
129	        payloadKey,
130	        returnResourceIdInLocationHeader,
131	        headers,
132	      });
133	    };
134	  }
135	
136	  public updateRequest({
137	    method,
138	    path = "",
139	    urlParamKeys = [],
140	    queryParamKeys = [],
141	    catchNotFound = false,
142	    keyTransform,
143	    payloadKey,
144	    returnResourceIdInLocationHeader,
145	    headers,
146	  }: RequestArgs) {
147	    return async (query: any = {}, payload: any = {}) => {
148	      const baseParams = this.#getBaseParams?.() ?? {};
149	
150	      // Filter query parameters by queryParamKeys
151	      const queryParams =
152	        queryParamKeys.length > 0
153	          ? (pick(query, queryParamKeys) as any)
154	          : undefined;
155	
156	      // Add filtered query parameters to base parameters
157	      const allUrlParamKeys = [...Object.keys(baseParams), ...urlParamKeys];
158	      const urlParams = {
159	        ...baseParams,
160	        ...pick(query, allUrlParamKeys),
161	      };
162	
163	      // Transform keys of queryParams
164	      if (keyTransform) {
165	        this.#transformKey(queryParams, keyTransform);
166	      }
167	
168	      return this.#requestWithParams({
169	        method,
170	        path,
171	        payload,
172	        urlParams,
173	        queryParams,
174	        catchNotFound,
175	        payloadKey,
176	        returnResourceIdInLocationHeader,
177	        headers,
178	      });
179	    };
180	  }
181	
182	  async #requestWithParams({
183	    method,
184	    path,
185	    payload,
186	    urlParams,
187	    queryParams,
188	    catchNotFound,
189	    payloadKey,
190	    returnResourceIdInLocationHeader,
191	    headers,
192	  }: {
193	    method: Method;
194	    path: string;
195	    payload: any;
196	    urlParams: any;
197	    queryParams?: Record<string, string>;
198	    catchNotFound: boolean;
199	    payloadKey?: string;
200	    returnResourceIdInLocationHeader?: { field: string };
201	    headers?: [string, string][] | Record<string, string> | Headers;
202	  }) {
203	    const requestOptions = { ...this.#client.getRequestOptions() };
204	    const requestHeaders = new Headers([
205	      ...new Headers(requestOptions.headers).entries(),
206	      ["authorization", `Bearer ${await this.#client.getAccessToken()}`],
207	      ["accept", "application/json, text/plain, */*"],
208	      ...new Headers(headers).entries(),
209	    ]);
210	
211	    const searchParams: Record<string, string> = {};
212	
213	    // Add payload parameters to search params if method is 'GET'.
214	    if (method === "GET") {
215	      Object.assign(searchParams, payload);
216	    } else if (requestHeaders.get("content-type") === "text/plain") {
217	      // Pass the payload as a plain string if the content type is 'text/plain'.
218	      requestOptions.body = payload as unknown as string;
219	    } else if (payload instanceof FormData) {
220	      requestOptions.body = payload;
221	    } else {
222	      // Otherwise assume it's JSON and stringify it.
223	      requestOptions.body =
224	        payloadKey && typeof payload[payloadKey] === "string"
225	          ? payload[payloadKey]
226	          : JSON.stringify(payloadKey ? payload[payloadKey] : payload);
227	    }
228	
229	    if (
230	      requestOptions.body &&
231	      !requestHeaders.has("content-type") &&
232	      !(payload instanceof FormData)
233	    ) {
234	      requestHeaders.set("content-type", "application/json");
235	    }
236	
237	    if (queryParams) {
238	      Object.assign(searchParams, queryParams);
239	    }
240	
241	    const url = new URL(this.#getBaseUrl());
242	    const pathTemplate = parseTemplate(joinPath(this.#basePath, path));
243	
244	    url.pathname = joinPath(url.pathname, pathTemplate.expand(urlParams));
245	    url.search = stringifyQueryParams(searchParams);
246	
247	    try {
248	      const res = await fetchWithError(url, {
249	        ...requestOptions,
250	        headers: requestHeaders,
251	        method,
252	        ...(this.#client.timeout
253	          ? { signal: AbortSignal.timeout(this.#client.timeout) }
254	          : {}),
255	      });
256	
257	      // now we get the response of the http request
258	      // if `resourceIdInLocationHeader` is true, we'll get the resourceId from the location header field
259	      // todo: find a better way to find the id in path, maybe some kind of pattern matching
260	      // for now, we simply split the last sub-path of the path returned in location header field
261	      if (returnResourceIdInLocationHeader) {
262	        const locationHeader = res.headers.get("location");
263	
264	        if (typeof locationHeader !== "string") {
265	          throw new Error(
266	            `location header is not found in request: ${res.url}`,
267	          );
268	        }
269	
270	        const resourceId = locationHeader.split(SLASH).pop();
271	        if (!resourceId) {
272	          // throw an error to let users know the response is not expected
273	          throw new Error(
274	            `resourceId is not found in Location header from request: ${res.url}`,
275	          );
276	        }
277	
278	        // return with format {[field]: string}
279	        const { field } = returnResourceIdInLocationHeader;
280	        return { [field]: resourceId };
281	      }
282	
283	      if (
284	        Object.entries(headers || []).find(
285	          ([key, value]) =>
286	            key.toLowerCase() === "accept" &&
287	            value === "application/octet-stream",
288	        )
289	      ) {
290	        return await res.arrayBuffer();
291	      }
292	
293	      return await parseResponse(res);
294	    } catch (err) {
295	      if (
296	        err instanceof NetworkError &&
297	        err.response.status === 404 &&
298	        catchNotFound
299	      ) {
300	        return null;
301	      }
302	      throw err;
303	    }
304	  }
